Waypost.RegisterSteps("horde/05-stonetalon-mountains", function() return {
	{ title = "Taskmaster Fizzule", note = "On the way north from Seereth's camp, keep east of the road to the Venture Co. tower north of the Sludge Fen. Before you go near Fizzule, use Flare Gun to fire two flares, then target him and /salute: he attacks anyone who comes in without signalling first.", only = { classes = {"ROGUE"} }, goals = {
		{ t = "turnin", quest = 2458, title = "Deep Cover", npc = "Taskmaster Fizzule", map = 1413, x = 55.44, y = 5.56, era = true },
