		{ t = "note", text = "Mission: Possible But Not Probable is for level 23 or more: the tower's drones are 25 and Gallywix a 23 elite. Do it when you can, with a group, from the Class guide Poisons (Horde)." },
	} },
	{ title = "Kadrak", note = "From Seereth's camp head north-east across the Barrens to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. Kadrak stands on the watch tower of the Mor'shan Rampart where the road enters Ashenvale.", goals = {
		{ t = "turnin", quest = 6541, title = "Report to Kadrak", npc = "Kadrak", map = 1413, x = 48.12, y = 5.42, era = true },
	} },
	{ title = "Into Ashenvale", goals = {
