	} },
	{ title = "Splintertree Post", note = "Splintertree Post is just north up the road. Coming in from the south, the flight master and Senani Thunderheart's hunt board at Night Run come first, then the vendors. Kuray'bin at the lumber camp offers Ashenvale Outrunners: leave it for the next Ashenvale visit, at 26.", goals = {
		{ t = "getfp", npc = "Vhulgra", map = 1440, x = 73.18, y = 61.59, era = true, location = "Splintertree Post" },
		{ t = "turnin", quest = 6382, title = "The Ashenvale Hunt", npc = "Senani Thunderheart", map = 1440, x = 73.78, y = 61.46, era = true },
		{ t = "turnin", quest = 6383, title = "The Ashenvale Hunt", npc = "Senani Thunderheart", map = 1440, x = 73.78, y = 61.46, era = true, qlvl = 20 },
		{ t = "note", text = "Senani's hunt targets (Ursangous, Shadumbra, Sharptalon) are for the next Ashenvale visit, at 26." },
		{ t = "vendor" },
	} },
	{ title = "Va'xug Firefure", note = "On the way west, Va'xug Firefure is stuck in a ravine south of the main road, south-east of Astranaar. Shadowhorn Stags and Ashenvale Bears roam the woods all around it.", goals = {
