		{ t = "turnin", quest = 98251, title = "Never Coming Back", npc = "Va'xug Firefure", map = 1440, x = 40.46, y = 61.42, era = true },
		{ t = "accept", quest = 98252, title = "A Void Path", npc = "Va'xug Firefure", map = 1440, x = 40.46, y = 61.42, era = true, qlvl = 23 },
	} },
	{ title = "A Void Path", note = "Steer Va'xug's Eye of Kilrogg out of the ravine to the main road within four minutes; if the channel breaks, ask Va'xug again.", goals = {
