		{ t = "level", npc = "Screeching Roguefeather", map = 1441, x = 27.17, y = 52.24, era = true, level = 29, mobLevel = 30, note = "grind on Screeching Roguefeather" },
	} },
	{ title = "The Screeching Canyon: kill these as you meet them", note = "South of Darkcloud, the harpies of Roguefeather Den. Grenka Bloodscreech (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are Jandia's; her Stolen Freewind Supplies lie on the ground along the foot of the cliff and in the cave up on top.", goals = {
		{ t = "kill", quest = 98070, title = "Stop the Screeching", map = 1441, x = 27.17, y = 52.24, era = true, count = 5, target = "Screeching Roguefeather", oi = 2, mobLevel = 30, spots = "26.7,52.8;27.9,50.5;26.9,55.6;27.3,47.7" },
		{ t = "kill", quest = 98070, title = "Stop the Screeching", map = 1441, x = 26.72, y = 52.1, era = true, count = 5, target = "Screeching Windcaller", oi = 3, mobLevel = 30, spots = "26.6,53.2;26.3,56" },
