	{ title = "Level 32.5", note = "Desolace's quests are 33-38. Still below 32.5 after the raceway's hand-ins? Keep killing the Sparkleshell Snappers on the flats just north of the raceway until level 32.5. Or, with a group, run the Scarlet Monastery dungeon (Graveyard or Library) instead.", when = {{ k = "level", op = "<", n = 32 }}, goals = {
		{ t = "goto", map = 1441, x = 77.5, y = 70.5, era = true, text = "Sparkleshell Snappers" },
