	} },
	{ title = "Freewind Post", note = "West back to Freewind Post. Cliffwatcher Longhorn stands in the middle of the post, on the way to the flight master.", goals = {
		{ t = "accept", quest = 5361, title = "Family Tree", npc = "Cliffwatcher Longhorn", map = 1441, x = 45.67, y = 50.74, era = true, qlvl = 35, note = "Cliffwatcher Longhorn: for Nataka Longhorn in Desolace, next" },
		{ t = "vendor" },
	} },
