	} },
	{ title = "Kodo Graveyard", note = "Use Smeed's Kodo Kombobulator on an Aged, Dying or Ancient Kodo in the graveyard and walk the tamed kodo back to Smeed. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time.", goals = {
		{ t = "use", map = 1443, x = 51, y = 58.5, era = true, item = 13892, itemName = "Kodo Kombobulator", note = "on an Aged, Dying or Ancient Kodo in the graveyard; don't kill it", text = "Kodo Kombobulator" },
		{ t = "talk", quest = 5561, title = "Kodo Roundup", npc = "Aged Kodo", map = 1443, x = 60.6, y = 61.6, era = true, oi = 1, note = "the tamed kodo, at Smeed's camp: talk to it, five times" },
	} },
	{ title = "Scrabblescrew's Camp", goals = {
		{ t = "turnin", quest = 5561, title = "Kodo Roundup", npc = "Smeed Scrabblescrew", map = 1443, x = 60.86, y = 61.86, era = true },
	} },
	{ title = "Level 33", note = "Shadowprey's Hand of Iruxos and the coast's naga want 33. Below that? The Scorpashi Lashers on the slopes north of Smeed's camp are on your way west: kill them until level 33. Or, with a group, run the Scarlet Monastery dungeon (Library) instead.", when = {{ k = "level", op = "<", n = 33 }}, goals = {
		{ t = "goto", map = 1443, x = 59.9, y = 54.6, era = true, text = "Scorpashi Lashers" },
		{ t = "level", npc = "Scorpashi Lasher", map = 1443, x = 60.83, y = 54.52, era = true, level = 33, mobLevel = 35, note = "grind on Scorpashi Lasher" },
	} },
	{ title = "Shadowprey Village", note = "Head west to the troll village on the coast, keeping clear of the Gelkis Village on the way. Aka'rai stands on the path just north of the village.\nAka'rai may not be here on Forever: if Aka'rai doesn't offer Hate the Hatefury, skip it.", goals = {
		{ t = "accept", quest = 97265, title = "Hate the Hatefury", npc = "Aka'rai", map = 1443, x = 25.35, y = 67.17, era = true, qlvl = 33, optional = true, note = "Aka'rai: the Hatefury satyrs of Sargeron, later in this guide" },
		{ t = "accept", quest = 5381, title = "Hand of Iruxos", npc = "Taiga Wisemane", map = 1443, x = 25.82, y = 68.21, era = true, qlvl = 38 },
		{ t = "sethome", npc = "Innkeeper Sikewa", map = 1443, x = 24.09, y = 68.21, era = true, location = "Shadowprey Village" },
		{ t = "accept", quest = 5763, title = "Hunting in Stranglethorn", npc = "Roon Wildmane", map = 1443, x = 25.05, y = 72.27, era = true, qlvl = 31, note = "Roon Wildmane: for Hemet Nesingwary in Stranglethorn, next guide" },
		{ t = "accept", quest = 6143, title = "Other Fish to Fry", npc = "Drulzegar Skraghook", map = 1443, x = 23.32, y = 72.87, era = true, qlvl = 36 },
		{ t = "accept", quest = 6142, title = "Clam Bait", npc = "Mai'Lahii", map = 1443, x = 22.64, y = 71.97, era = true, qlvl = 35 },
		{ t = "getfp", npc = "Thalon", map = 1443, x = 21.6, y = 74.13, era = true, location = "Shadowprey Village", note = "Thalon, at the village's south-west end" },
	} },
	{ title = "Ethel Rethor", note = "Head north along the coast, then inland to the ruined tower of Ethel Rethor: Azore Aldamort waits inside. The coast's clams and naga come after Thunder Axe Fortress, on one walk north to Ranazjar Isle.", goals = {
		{ t = "accept", quest = 5741, title = "Sceptre of Light", npc = "Azore Aldamort", map = 1443, x = 38.88, y = 27.16, era = true, qlvl = 33 },
	} },
	{ title = "Thunder Axe Fortress", note = "Head east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it. Hand of Iruxos: clear the middle of the largest building, then use the Demon Pick on the red Hand of Iruxos Crystal there. A Demon Spirit (37) comes out: kill it for the Demon Box.", goals = {
		{ t = "collect", quest = 1435, title = "The Burning of Spirits", map = 1443, x = 55, y = 26.5, era = true, count = 15, item = 6435, itemName = "Infused Burning Gem", oi = 1, mobLevel = 32, src = "Burning Blade Adept, Burning Blade Shadowmage, Burning Blade Felsworn and others", srcKind = "npc", spots = "55,26.5;57.1,25.8;55.6,29.8;57.3,28.3;52.7,29" },
		{ t = "collect", quest = 5741, title = "Sceptre of Light", map = 1443, x = 55.2, y = 30.1, era = true, count = 1, item = 15750, itemName = "Sceptre of Light", oi = 1, note = "On the top floor", src = "Burning Blade Seer", srcKind = "npc" },
		{ t = "use", quest = 5381, title = "Hand of Iruxos", map = 1443, x = 55, y = 26.7, era = true, item = 14523, itemName = "Demon Pick", oi = 1, note = "Demon Pick, on the Hand of Iruxos Crystal" },
		{ t = "collect", quest = 5381, title = "Hand of Iruxos", map = 1443, x = 55, y = 26.6, era = true, count = 1, item = 13542, itemName = "Demon Box", oi = 1, src = "Demon Spirit", srcKind = "npc" },
		{ t = "collect", map = 1443, x = 54.99, y = 26.19, era = true, count = 1, item = 20310, itemName = "Flayed Demon Skin", mobLevel = 32, optional = true, src = "Burning Blade Adept, Burning Blade Augur, Burning Blade Reaver and others", srcKind = "npc", spots = "55,26.5;57.1,25.8;57.3,28.3;55.7,29.8;54.4,33.2" },
		{ t = "accept", quest = 1480, title = "The Corrupter", item = 20310, itemName = "Flayed Demon Skin", qlvl = 33, optional = true },
	} },
	{ title = "Ethel Rethor", note = "Back west to Azore.", goals = {
		{ t = "turnin", quest = 5741, title = "Sceptre of Light", npc = "Azore Aldamort", map = 1443, x = 38.88, y = 27.16, era = true },
		{ t = "accept", quest = 6027, title = "Book of the Ancients", npc = "Azore Aldamort", map = 1443, x = 38.88, y = 27.16, era = true, qlvl = 38 },
	} },
	{ title = "Rackmore's Log", note = "Rackmore's Log lies on the ground just south-west of Azore's tower, on the way down to the shore: read it. Its two keys drop only while you have the quest.", goals = {
		{ t = "accept", quest = 6161, title = "Claim Rackmore's Treasure!", npc = "Rackmore's Log", map = 1443, x = 36.07, y = 30.41, era = true, qlvl = 36 },
	} },
	{ title = "Clam beds", note = "West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a Soft-shelled Clam. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry Rackmore's Silver Key, about one in seven.", goals = {
		{ t = "interact", quest = 6142, title = "Clam Bait", npc = "Giant Softshell Clam", map = 1443, x = 30.6, y = 31.9, era = true, oi = 1, note = "Giant Softshell Clams, on the sea floor", spots = "30.6,31.9;31.8,27.4;34,33.4;26,37.8;34.8,24.1" },
