Waypost.RegisterSteps("horde/30-40/06-badlands", function() return {
	{ title = "Into the Badlands", note = "Head for the Thandol Span, the great bridge at Arathi's southern edge, cross it and follow the road south through the Wetlands to the Dun Algaz tunnel into Loch Modan. Thelsamar, the dwarf town on the road in the middle of Loch Modan, has guards who attack the Horde: leave the road before it and pass the town on the hills to its west. The road leaves Loch Modan to the south into the Badlands; follow it to the goblin camp in the Valley of Fangs.", goals = {
		{ t = "goto", map = 1418, x = 42.3, y = 52.8, era = true, text = "Valley of Fangs" },
	} },
	{ title = "Valley of Fangs", goals = {
		{ t = "turnin", quest = 1106, title = "Martek the Exiled", npc = "Martek the Exiled", map = 1418, x = 42.22, y = 52.69, era = true, note = "Martek the Exiled: Fizzle's letter from the Shimmering Flats" },
		{ t = "accept", quest = 1108, title = "Indurium", npc = "Martek the Exiled", map = 1418, x = 42.22, y = 52.69, era = true, qlvl = 39 },
		{ t = "accept", quest = 703, title = "Barbecued Buzzard Wings", npc = "Rigglefuzz", map = 1418, x = 42.39, y = 52.93, era = true, qlvl = 40 },
	} },
	{ title = "The Dustbowl", note = "Head west along the road towards Kargath; Lotwil's camp sits in the Dustbowl halfway there.", goals = {
		{ t = "accept", quest = 710, title = "Study of the Elements: Rock", npc = "Lotwil Veriatus", map = 1418, x = 25.95, y = 44.87, era = true, qlvl = 37 },
	} },
	{ title = "Kargath", note = "Kargath is the Horde fortress built into the cliffs at the zone's western edge. Neeka Bloodscar stands on Kargath's upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart.", goals = {
